import{_ as o,o as e,c as a,ag as l}from"./chunks/framework.B5ULsuav.js";const d=JSON.parse('{"title":"轻轻意守手指脚趾","description":"","frontmatter":{},"headers":[],"relativePath":"60-原文段落/修行即生活-意守手指脚趾.md","filePath":"60-原文段落/修行即生活-意守手指脚趾.md","lastUpdated":1778155802000}'),r={name:"60-原文段落/修行即生活-意守手指脚趾.md"};function _(i,t,u,c,n,q){return e(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="轻轻意守手指脚趾" tabindex="-1">轻轻意守手指脚趾 <a class="header-anchor" href="#轻轻意守手指脚趾" aria-label="Permalink to &quot;轻轻意守手指脚趾&quot;">​</a></h1><blockquote><p>来源：修行即生活（20090111b）</p></blockquote><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><blockquote><p>&quot;轻轻意守的意思就是说心里有这个意识，轻轻想一下手指的感觉、脚趾的感觉就好了。好像你们现在天气凉，你们在电脑旁有些人会觉得两个脚很冷，这个冷的感觉是什么？就是你轻轻地在意守。假如说你好像有些人在跟人家说笑话说得很开心，他身上有什么感觉都不知道，被精神排遣了。或者有些人在看电视、看录像太集中精神了，他周围发生的事情他甚至都不知道。所以轻轻意守的意思就说你会感知你手脚有什么感觉，是热是冷，这个就是轻轻意守。但不要全神贯注去守。修炼的过程，千万不要全神贯注，精神也紧张，身体也紧张，人体场也僵化，毫无好处，无一好处，所以要轻轻意守。&quot;</p></blockquote><blockquote><p>&quot;意守手指脚趾就等于意守全身。我为什么突出叫你们意守手指脚趾呢？因为我们的手指和脚趾很远，很容易守得到。你一守到的时候，你就会觉得你的精神很自然的是在意守你的全身。很自然的。其实是同一个道理，我只叫你们意守全身，你们会觉得没着落，比较难理解。但是我告诉你们轻轻意守手指脚趾，你们很容易下手了。&quot;</p></blockquote><blockquote><p>&quot;古人经常说五心相应，五心在哪里？就是头上顶心百会穴，手上手心劳宫穴，脚上脚心涌泉穴。但是我为什么从来不提头上顶心呢？因为我们在练功的历程之中，头顶心常有一种微微的痛感，或者是微微的重压感。总之修炼的人经常头顶是有感觉的。既然会有感觉了，就是不知不觉在意守了。如果叫大家再去意守，那就意念太重了。&quot;</p></blockquote><blockquote><p>&quot;我从来不提头顶，只是提手脚。大家轻轻意守手指脚趾，这个时候头上有感觉你们都会知道，不用我说你们也会知道。但是如果我说了，你们注意力加重一点，那个头就不舒服了。我就是用转移注意力的方法使它五心平衡。&quot;</p></blockquote><h2 id="关键要点" tabindex="-1">关键要点 <a class="header-anchor" href="#关键要点" aria-label="Permalink to &quot;关键要点&quot;">​</a></h2><ul><li>轻轻意守=感知手脚的冷热感觉，不是全神贯注</li><li>意守手指脚趾=意守全身，但更容易下手</li><li>故意不提头顶（五心之一）→ 转移注意力使五心平衡</li><li>绝对不要死守——精神紧张、身体紧张、人体场僵化</li></ul>',9)])])}const p=o(r,[["render",_]]);export{d as __pageData,p as default};
